import { pcaChainDigest } from '../pca-grant-details';

/**
 * Shared vectors for the `pca_grant` authorization-details type (conformance/pca-grant-vectors.json). The expected results
 * are written here by hand, not read back from the implementation, so the TypeScript reference is tested against them
 * like every native. Only the chain digests are computed (the canonical hash is the one thing every verifier must agree on).
 * Generated by scripts/gen-conformance-pca-grant.ts.
 */
const IDS = ['capA', 'capB', 'capC'];
const D1 = pcaChainDigest(IDS.slice(0, 1));
const D2 = pcaChainDigest(IDS.slice(0, 2));
const RS = 'https://api.example.com';
const ok = (extra: Record<string, unknown> = {}) => ({ type: 'pca_grant', chain_digest: D1, chain_len: 1, ...extra });
const accept = { ok: true };
const refuse = (code: string) => ({ ok: false, code });

export function buildPcaGrantVectors() {
  const detail = [
    { name: 'minimal', input: ok(), expect: accept },
    { name: 'full', input: ok({ chain_ref: 'https://as.example.com/pca/grants/g_1', bundle_revision: 7, locations: [RS] }), expect: accept },
    { name: 'wrong-type', input: { ...ok(), type: 'payment_initiation' }, expect: refuse('bad_type') },
    { name: 'type-missing', input: { chain_digest: D1, chain_len: 1 }, expect: refuse('bad_type') },
    { name: 'not-an-object', input: 'pca_grant', expect: refuse('bad_entry') },
    { name: 'array-is-not-an-object', input: [ok()], expect: refuse('bad_entry') },
    { name: 'unknown-member', input: ok({ extra: 1 }), expect: refuse('unknown_member') },
    { name: 'actions-refused', input: ok({ actions: ['read'] }), expect: refuse('refused_member') },
    { name: 'datatypes-refused', input: ok({ datatypes: ['x'] }), expect: refuse('refused_member') },
    { name: 'identifier-refused', input: ok({ identifier: 'x' }), expect: refuse('refused_member') },
    { name: 'privileges-refused', input: ok({ privileges: ['x'] }), expect: refuse('refused_member') },
    { name: 'digest-missing', input: { type: 'pca_grant', chain_len: 1 }, expect: refuse('bad_chain_digest') },
    { name: 'digest-padded', input: ok({ chain_digest: `${D1}=` }), expect: refuse('bad_chain_digest') },
    { name: 'digest-short', input: ok({ chain_digest: D1.slice(0, 42) }), expect: refuse('bad_chain_digest') },
    { name: 'digest-standard-alphabet', input: ok({ chain_digest: 'A+/'.padEnd(43, 'A') }), expect: refuse('bad_chain_digest') },
    { name: 'digest-non-canonical-tail', input: ok({ chain_digest: `${D1.slice(0, 42)}B` }), expect: refuse('bad_chain_digest') },
    { name: 'digest-not-a-string', input: ok({ chain_digest: 5 }), expect: refuse('bad_chain_digest') },
    { name: 'len-missing', input: { type: 'pca_grant', chain_digest: D1 }, expect: refuse('bad_chain_len') },
    { name: 'len-zero', input: ok({ chain_len: 0 }), expect: refuse('bad_chain_len') },
    { name: 'len-seventeen', input: ok({ chain_len: 17 }), expect: refuse('bad_chain_len') },
    { name: 'len-sixteen', input: ok({ chain_len: 16 }), expect: accept },
    { name: 'len-fraction', input: ok({ chain_len: 1.5 }), expect: refuse('bad_chain_len') },
    { name: 'len-string', input: ok({ chain_len: '1' }), expect: refuse('bad_chain_len') },
    { name: 'ref-http', input: ok({ chain_ref: 'http://as.example.com/g' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-userinfo', input: ok({ chain_ref: 'https://user@as.example.com/g' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-fragment', input: ok({ chain_ref: 'https://as.example.com/g#x' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-space', input: ok({ chain_ref: 'https://as.example.com/a b' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-backslash', input: ok({ chain_ref: 'https://as.example.com\\evil' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-no-host', input: ok({ chain_ref: 'https:///g' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-empty', input: ok({ chain_ref: '' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-non-ascii', input: ok({ chain_ref: 'https://as.example.com/é' }), expect: refuse('bad_chain_ref') },
    { name: 'ref-too-long', input: ok({ chain_ref: `https://as.example.com/${'a'.repeat(2030)}` }), expect: refuse('bad_chain_ref') },
    { name: 'ref-query-ok', input: ok({ chain_ref: 'https://as.example.com?g=1' }), expect: accept },
    { name: 'revision-zero', input: ok({ bundle_revision: 0 }), expect: accept },
    { name: 'revision-negative', input: ok({ bundle_revision: -1 }), expect: refuse('bad_bundle_revision') },
    { name: 'revision-fraction', input: ok({ bundle_revision: 1.5 }), expect: refuse('bad_bundle_revision') },
    { name: 'revision-string', input: ok({ bundle_revision: '7' }), expect: refuse('bad_bundle_revision') },
    { name: 'locations-empty', input: ok({ locations: [] }), expect: refuse('bad_locations') },
    { name: 'locations-not-array', input: ok({ locations: RS }), expect: refuse('bad_locations') },
    { name: 'locations-http', input: ok({ locations: ['http://api.example.com'] }), expect: refuse('bad_locations') },
    { name: 'locations-nine', input: ok({ locations: Array.from({ length: 9 }, (_, i) => `https://h${i}.example.com`) }), expect: refuse('bad_locations') },
    { name: 'locations-eight', input: ok({ locations: Array.from({ length: 8 }, (_, i) => `https://h${i}.example.com`) }), expect: accept },
  ];

  const array = [
    { name: 'empty-array', input: [], expect: { ok: true, count: 0 } },
    { name: 'one', input: [ok()], expect: { ok: true, count: 1 } },
    { name: 'other-types-ignored', input: [{ type: 'payment_initiation', amount: 5 }, ok()], expect: { ok: true, count: 1 } },
    { name: 'only-other-types', input: [{ type: 'payment_initiation' }], expect: { ok: true, count: 0 } },
    { name: 'bad-pca-entry-refuses-all', input: [ok(), ok({ chain_len: 0 })], expect: refuse('bad_chain_len') },
    { name: 'entry-without-type', input: [{ chain_digest: D1 }], expect: refuse('bad_entry') },
    { name: 'entry-not-object', input: [ok(), 'x'], expect: refuse('bad_entry') },
    { name: 'not-an-array', input: ok(), expect: refuse('not_an_array') },
    { name: 'null', input: null, expect: refuse('not_an_array') },
    { name: 'seventeen-entries', input: Array.from({ length: 17 }, () => ({ type: 'x' })), expect: refuse('too_many_details') },
    { name: 'sixteen-entries', input: Array.from({ length: 16 }, () => ({ type: 'x' })), expect: { ok: true, count: 0 } },
  ];

  const d1 = ok({ locations: [RS] });
  const d2 = { type: 'pca_grant', chain_digest: D2, chain_len: 2 };
  const presented = (chain_ids: string[], proof_verified = true, resource = RS) => ({ resource, chain_ids, proof_verified });
  const presentation = [
    { name: 'exact-chain', details: [d1], presented: presented(['capA']), expect: { allow: true, index: 0 } },
    { name: 'delegated-chain-extends-the-named-prefix', details: [d1], presented: presented(['capA', 'capB', 'capC']), expect: { allow: true, index: 0 } },
    { name: 'token-alone-is-never-enough', details: [d1], presented: presented(['capA'], false), expect: { allow: false, code: 'proof_required' } },
    { name: 'no-details', details: [], presented: presented(['capA']), expect: { allow: false, code: 'no_detail' } },
    { name: 'no-details-and-no-proof', details: [], presented: presented(['capA'], false), expect: { allow: false, code: 'no_detail' } },
    { name: 'chain-from-another-root', details: [d1], presented: presented(['capZ']), expect: { allow: false, code: 'chain_mismatch' } },
    { name: 'chain-shorter-than-named', details: [d2], presented: presented(['capA']), expect: { allow: false, code: 'chain_mismatch' } },
    { name: 'second-hop-differs', details: [d2], presented: presented(['capA', 'capX']), expect: { allow: false, code: 'chain_mismatch' } },
    { name: 'two-hop-detail-matches-longer-chain', details: [d2], presented: presented(['capA', 'capB', 'capC']), expect: { allow: true, index: 0 } },
    { name: 'wrong-location', details: [d1], presented: presented(['capA'], true, 'https://other.example.com'), expect: { allow: false, code: 'wrong_location' } },
    { name: 'second-detail-passes', details: [d1, d2], presented: presented(['capA', 'capB'], true, 'https://other.example.com'), expect: { allow: true, index: 1 } },
    { name: 'no-locations-means-any-resource', details: [d2], presented: presented(['capA', 'capB'], true, 'https://other.example.com'), expect: { allow: true, index: 0 } },
  ];

  return {
    format: 1,
    about: 'Conformance vectors for the pca_grant OAuth authorization-details type (RFC 9396). Digest: sha-256 (unpadded base64url) of the strict-canonical JSON {"d":"atlas-pca/pca-grant-chain/v1","ids":[...]}. Generated by scripts/gen-conformance-pca-grant.ts.',
    max_details: 16,
    digest: [
      { ids: IDS.slice(0, 1), digest: D1 },
      { ids: IDS.slice(0, 2), digest: D2 },
      { ids: IDS, digest: pcaChainDigest(IDS) },
    ],
    detail,
    array,
    presentation,
  };
}
